const renderGridRef = useRef<
  ((tier: TierLevel, targetItem?: SearchResultItem | null, parentProps?: GridCellProperties | null) => Promise<void>) | null
>(null);

// Fallback Geometric Grid Helpers
const renderFallbackTier1 = useCallback(
  (L: typeof import("leaflet"), targetItem: SearchResultItem | null) => {
    if (!mapInstanceRef.current || !gridLayerGroupRef.current) return;
    const { north, south, west, east } = GRID_ORIGIN_BOUNDS;
    const latStep = (north - south) / 10;
    const lngStep = (east - west) / 10;

    for (let r = 0; r < 10; r++) {
      for (let c = 0; c < 10; c++) {
        const cellId = `${r}${c}`;
        const cellSouth = south + r * latStep;
        const cellNorth = south + (r + 1) * latStep;
        const cellWest = west + c * lngStep;
        const cellEast = west + (c + 1) * lngStep;

        const isUnmasked = UAE_UNMASKED_CELLS.includes(cellId);
        const isHighlightTarget = targetItem ? cellId === targetItem.tiers.tier1 : false;
        const isSelected = isHighlightTarget || selectedCellIdRef.current === cellId;

        const bounds: [[number, number], [number, number]] = [
          [cellSouth, cellWest],
          [cellNorth, cellEast],
        ];

        if (isUnmasked) {
          const fillColor = isSelected ? "#1B8CFE" : "#FFFFFF";
          const fillOpacity = isSelected ? 0.88 : 0.70;
          const strokeColor = isSelected ? "#0000FF" : "rgba(37, 99, 235, 0.45)";
          const strokeWidth = isSelected ? 2.2 : 1.2;

          const rect = L.rectangle(bounds, {
            color: strokeColor,
            weight: strokeWidth,
            fillColor,
            fillOpacity,
            className: isSelected ? "selected-grid-cell" : "enabled-grid-cell",
          });

          rect.on("mouseover", () => {
            if (selectedCellIdRef.current !== cellId) {
              rect.setStyle({ fillOpacity: 0.85, color: "#1D4ED8", weight: 1.8 });
            }
          });
          rect.on("mouseout", () => {
            if (selectedCellIdRef.current !== cellId) {
              rect.setStyle({ fillOpacity: 0.70, color: "rgba(37, 99, 235, 0.45)", weight: 1.2 });
            }
          });

          rect.on("click", (e) => {
            L.DomEvent.stopPropagation(e);
            selectedCellIdRef.current = cellId;
            setSelectedCellId(cellId);
            setSelectedCellProps({ hierarchyCode: cellId, code: cellId });
            setActiveTier(2);
            mapInstanceRef.current?.flyToBounds(bounds, {
              duration: 1.0,
              easeLinearity: 0.25,
              padding: [24, 24],
            });
            setBreadcrumbs([
              { tier: 1, label: "UAE (Tier 1)", code: "UAE" },
              { tier: 2, label: `Cell ${cellId} (Tier 2)`, code: cellId, bounds },
            ]);
            renderGridRef.current?.(2, targetItem, { code: cellId, hierarchyCode: cellId });
          });

          rect.addTo(gridLayerGroupRef.current);

          const textColor = isSelected ? "#FFFFFF" : "#0F172A";
          rect.bindTooltip(
            `<div style="font-family: var(--font-cairo), Cairo, sans-serif; font-size: 13px; font-weight: 700; color: ${textColor}; text-align: center; line-height: 1.2; text-shadow: ${isSelected ? "none" : "0 0 3px rgba(255,255,255,0.9), 0 0 1px #FFFFFF"}; user-select: none;">${cellId}</div>`,
            { permanent: true, direction: "center", className: "grid-cell-tooltip" }
          );
        } else if (gridTypeRef.current === "full-grid") {
          const rect = L.rectangle(bounds, {
            color: "#DEDEDE",
            weight: 0.8,
            fillColor: "url(#uaeDisabledHatchPattern)",
            fillOpacity: 1,
            className: "disabled-grid-cell",
            interactive: false,
          });
          rect.addTo(gridLayerGroupRef.current);

          rect.bindTooltip(
            `<div style="font-family: var(--font-cairo), Cairo, sans-serif; font-size: 13px; font-weight: 700; color: #94A3B8; text-align: center; line-height: 1.2; user-select: none;">${cellId}</div>`,
            { permanent: true, direction: "center", className: "grid-cell-tooltip" }
          );
        }
      }
    }

    L.polygon(UAE_BORDER_COORDINATES, {
      color: "#2563EB",
      weight: 2.2,
      dashArray: "6 5",
      fillColor: "rgba(0, 0, 255, 0.05)",
      fillOpacity: 0.05,
      interactive: false,
    }).addTo(gridLayerGroupRef.current);

    const uaeBounds: [[number, number], [number, number]] = [
      [TIER1_DEFAULT_BOUNDS.south, TIER1_DEFAULT_BOUNDS.west],
      [TIER1_DEFAULT_BOUNDS.north, TIER1_DEFAULT_BOUNDS.east],
    ];
    mapInstanceRef.current.flyToBounds(uaeBounds, { padding: [24, 24], duration: 1.0, easeLinearity: 0.25 });
  },
  []
);

