      mapInstanceRef.current.flyToBounds(pBounds, {
        duration: 1.0,
        easeLinearity: 0.25,
        padding: [24, 24],
      });
    }
    const cLat = (north + south) / 2;
    const cLng = (west + east) / 2;
    updatePinMarker(cLat, cLng);
  },
  [bindSvgLabel, renderPlotPOIs, updatePinMarker]
);
